(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n==null?'Sob consulta':(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 let selected=[];try{const value=JSON.parse(sessionStorage.getItem('up-compare')||'[]');if(Array.isArray(value))selected=[...new Set(value.filter(x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(x)))].slice(0,2);}catch{}
 const comparisonPage=!!$('#comparison-main');
 const bar=document.createElement('aside');bar.className='compare-bar';bar.hidden=true;bar.setAttribute('aria-label','Celulares selecionados para comparar');bar.innerHTML='<span id="compare-count" aria-live="polite"></span><a href="/comparar">Comparar celulares</a><button type="button" id="clear-comparison">Limpar</button>';if(!comparisonPage)document.body.append(bar);
 const message=document.createElement('p');message.className='commerce-toast';message.hidden=true;message.setAttribute('role','status');document.body.append(message);let timer;
 function say(text){message.textContent=text;message.hidden=false;clearTimeout(timer);timer=setTimeout(()=>message.hidden=true,5000);}
 function remember(){try{sessionStorage.setItem('up-compare',JSON.stringify(selected));}catch{}paint();}
 function paint(){document.querySelectorAll('[data-compare]').forEach(b=>{const on=selected.includes(b.dataset.compare);b.setAttribute('aria-pressed',String(on));b.textContent=on?'✓ Na comparação':'Comparar celular';});if(!comparisonPage){bar.hidden=!selected.length;bar.querySelector('#compare-count').textContent=selected.length+' de 2 selecionados';}}
 bar.querySelector('button').onclick=()=>{selected=[];remember();};
 document.addEventListener('click',e=>{const b=e.target.closest('[data-compare]');if(!b)return;const id=b.dataset.compare;if(selected.includes(id))selected=selected.filter(x=>x!==id);else{if(selected.length===2){say('Você já escolheu dois celulares. Remova um ou abra a comparação para trocar.');return;}selected.push(id);}remember();});
 document.addEventListener('up:products-rendered',paint);paint();
 if(!comparisonPage)return;
 let catalog=[],variantIndices=[0,0];
 async function load(){try{const r=await fetch('/api/catalog');if(!r.ok)throw Error('Não foi possível carregar os celulares.');const data=await r.json();catalog=data.products.filter(p=>['iPhone','Xiaomi'].includes(p.category));let mode='default';try{mode=localStorage.getItem('up-visitor-theme')||mode;}catch{}applyTheme({...data.settings,theme:mode==='default'?data.settings.theme:mode});selected=selected.filter(id=>catalog.some(p=>p.id===id));remember();$('#compare-loading').hidden=true;$('#compare-workspace').hidden=false;$('#compare-empty').hidden=catalog.length>0;$('#compare-controls').hidden=catalog.length===0;$('#compare-help').textContent=catalog.length===1?'Há um celular no catálogo. A comparação entre dois fica disponível quando houver outro modelo.':'Escolha dois celulares e as opções que você quer comparar.';controls();render();}catch(e){$('#compare-loading').textContent=e.message;$('#compare-retry').hidden=false;}}
 function controls(){for(let i=0;i<2;i++){const sel=$('#compare-model-'+i);sel.replaceChildren(new Option('Escolher celular',''));for(const p of catalog){if(p.id===selected[1-i])continue;sel.add(new Option(p.name,p.id));}sel.value=selected[i]||'';sel.onchange=()=>{selected[i]=sel.value;variantIndices[i]=0;try{sessionStorage.setItem('up-compare',JSON.stringify(selected));}catch{}controls();render();};}}
 function render(){const models=[0,1].map(i=>catalog.find(p=>p.id===selected[i])||null);const table=$('#comparison-table');table.hidden=!models.some(Boolean);$('#compare-help').hidden=models.every(Boolean);const variant=p=>p?.details?.variants||[];
 const current=models.map((p,i)=>{if(!p)return null;const variants=variant(p);if(variantIndices[i]>=variants.length)variantIndices[i]=0;return variants.length?variants[variantIndices[i]]:{price:p.price,stock:p.stock,color:p.details?.color,capacity:p.details?.capacity};});
 const field=(fn)=>models.map((p,i)=>p?esc(fn(p,current[i])||'Não informado'):'Escolha um celular');
 const rows=[['Preço',field((p,v)=>money(v.price))],['Armazenamento',field((p,v)=>v.capacity)],['Cor',field((p,v)=>v.color)],['Condição',field(p=>p.condition)],['Saúde da bateria',field(p=>p.condition==='Novo'?'Não se aplica':p.details?.battery==null?'Não informado':p.details.battery+'%')],['Disponibilidade',field((p,v)=>v.stock>0?'Em estoque':'Sem estoque')],['Garantia',field(p=>p.details?.warranty)],['Ficha técnica e itens inclusos',field(p=>p.details?.specs)]];
 table.innerHTML='<caption class="sr-only">Comparação dos celulares selecionados</caption><thead><tr><th scope="col" class="compare-label">Características</th>'+models.map((p,i)=>`<th scope="col">${p?`${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" referrerpolicy="no-referrer">`:''}<h2>${esc(p.name)}</h2>${variant(p).length?`<label>Opção de ${esc(p.name)}<select data-compare-option="${i}">${variant(p).map((v,j)=>`<option value="${j}" ${j===variantIndices[i]?'selected':''}>${esc([v.color,v.capacity].filter(Boolean).join(' · '))}${v.stock===0?' — sem estoque':''}</option>`).join('')}</select></label>`:''}`:'<h2>Segundo celular</h2><p>Selecione um modelo acima.</p>'}</th>`).join('')+'</tr></thead><tbody>'+rows.map(([name,values])=>`<tr><th scope="row">${name}</th>${values.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')+'<tr class="compare-links"><th scope="row">Saiba mais</th>'+models.map((p,i)=>{if(!p)return '<td></td>';const v=current[i],option=[v.color,v.capacity].filter(Boolean).join(' · '),wa='https://wa.me/553591558356?text='+encodeURIComponent(`Olá! ${v.stock>0?'Tenho interesse em':'Gostaria de consultar a reposição de'} ${p.name}${option?' ('+option+')':''}. Condição: ${p.condition}. Preço anunciado: ${money(v.price)}.\n${location.origin+'/produto/'+p.id}`);return `<td><a class="button orange" href="${esc(wa)}" target="_blank" rel="noopener noreferrer">${v.stock>0?'Tenho interesse':'Consultar reposição'} ↗</a><a class="compare-detail" href="/produto/${encodeURIComponent(p.id)}">Ver detalhes do produto</a></td>`;}).join('')+'</tr></tbody>';
 table.querySelectorAll('[data-compare-option]').forEach(sel=>sel.onchange=()=>{const slot=Number(sel.dataset.compareOption);variantIndices[slot]=Number(sel.value);render();table.querySelector(`[data-compare-option="${slot}"]`)?.focus();});$('#comparison-update').textContent=models.every(Boolean)?'Comparação atualizada.':'';
 }
 $('#compare-retry').onclick=()=>{$('#compare-retry').hidden=true;$('#compare-loading').textContent='Carregando celulares…';load();};load();
})();
